// 当日の提出者と、直近14日の対象者から未提出者を割り出す
const tz=$env.REPORT_TIMEZONE||'Asia/Tokyo';
const dateISO=new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const recs=$json.records||[];
const pk=c=>{const m=c.match(/_(\d+)$/);return m?m[1]:'';};
const isSub=f=>f&&Array.isArray(f.value)&&f.value[0]&&f.value[0].value&&typeof f.value[0].value==='object';
const norm=s=>s?String(s).replace(/[\s　]/g,''):null;
const items=[];
for(const rec of recs){let team=null;
  for(const[,f]of Object.entries(rec))if(f&&f.type==='DROP_DOWN'&&f.value){team=f.value;break;}
  for(const[,f]of Object.entries(rec)){if(!isSub(f))continue;
    for(const row of f.value){let date=null;const names={},files={};
      for(const[code,cell]of Object.entries(row.value)){if(!cell)continue;
        if(cell.type==='DATETIME'&&cell.value)date=String(cell.value).slice(0,10);
        else if(cell.type==='SINGLE_LINE_TEXT')names[pk(code)]=cell.value||null;
        else if(cell.type==='FILE')files[pk(code)]=Array.isArray(cell.value)?cell.value:[];}
      for(const k of Object.keys(files)){const fl=files[k]||[];if(!fl.length)continue;
        items.push({date,reporter:names[k]||null,team,fileKey:fl[0].fileKey,contentType:fl[0].contentType});}}}}
const today=items.filter(x=>x.date===dateISO);
// 対象者 = 直近14日に提出した人
const t=new Date(dateISO+'T00:00:00Z').getTime(), from=t-14*864e5;
const roster=new Map();
for(const x of items){if(!x.date||!x.reporter)continue;
  const d=new Date(x.date+'T00:00:00Z').getTime();
  if(d>=from&&d<=t)roster.set(norm(x.reporter),x.reporter);}
const sub=new Set(today.map(x=>norm(x.reporter)).filter(Boolean));
const missing=[...roster.entries()].filter(([n])=>!sub.has(n)).map(([,d])=>d);
if(!today.length)return[{json:{dateISO,empty:true,missing,rosterSize:roster.size}}];
return today.map((x,i)=>({json:{...x,dateISO,idx:i,total:today.length,missing,rosterSize:roster.size}}));

// 全員分を1通にまとめる（最後の1件が来たときに送信用データを作る）
const info=$('当日分と未提出者を集計').item.json;
let a=null;
try{const t=($json.content||[]).filter(c=>c.type==='text').map(c=>c.text).join('\n');
  let s=t.trim();const f=s.match(/```(?:json)?\s*([\s\S]*?)```/i);if(f)s=f[1].trim();
  const i=s.indexOf('{'),j=s.lastIndexOf('}');if(i>-1&&j>-1)s=s.slice(i,j+1);a=JSON.parse(s);}catch(e){a=null;}
const store=$getWorkflowStaticData('node');
if(!store.buf||store.date!==info.dateISO){store.buf=[];store.date=info.dateISO;}
store.buf.push({who:info.reporter||'（氏名不明）',team:info.team,a});
if(store.buf.length<info.total)return[];
const rows=store.buf;store.buf=[];
const L=[`📊 Libetee 日報まとめ（${info.dateISO}）`,'',`提出 ${rows.length}件 / 対象 ${info.rosterSize}名`,''];
let anyUrgent=false;
for(const r of rows){const mark=r.a&&r.a.urgent?'🚨 ':'';if(r.a&&r.a.urgent)anyUrgent=true;
  L.push(`${mark}■ ${r.who}さん${r.team?'（'+r.team+'）':''}`);
  L.push('  '+((r.a&&r.a.summary)||'（要約なし）'));
  if(r.a&&r.a.urgent&&r.a.urgent_reason)L.push('  ⚠️ '+r.a.urgent_reason);
  if(r.a&&Array.isArray(r.a.tomorrow)&&r.a.tomorrow.length)L.push('  → 明日: '+r.a.tomorrow.join('、'));
  L.push('');}
if(info.missing&&info.missing.length){L.push('【未提出】',...info.missing.map(n=>'・'+n+'さん'),'');}
else L.push('【未提出】なし（全員提出済み）','');
L.push('詳細はKintoneをご確認ください。');
const text=L.join('\n').slice(0,4000);
return[{json:{text,urgent:anyUrgent,title:L[0],body:L.slice(1).join('\n').trim()}}];

// 提出0件の日も「誰も出していない」ことを知らせる
const i=$json;
const L=[`📊 Libetee 日報まとめ（${i.dateISO}）`,'','本日の提出はありません。',''];
if(i.missing&&i.missing.length)L.push('【未提出】',...i.missing.map(n=>'・'+n+'さん'),'');
L.push('詳細はKintoneをご確認ください。');
const text=L.join('\n');
return[{json:{text,urgent:false,title:L[0],body:L.slice(1).join('\n').trim()}}];
